-- Which emptying animation fits each bag (see DSTB_EmptyAction). Generated by assets/DontSpillTheBeans/anim/build_bag_table.py
-- from bag_clips.json; regenerate it instead of editing by hand.
--   small / medium / large: plain bags by width (cases, boxes, satchels, totes); pack: backpacks, which hang leaning back.
--   hand / handl: bags whose model is skinned to the right / left HAND bone instead of the prop bone (the new Authentic Z
--   backpacks), so the hand itself turns the bag over.
--   none: keep the stock Loot animation (very long or very large containers, bags with no skinned hand model, worn-only models).
-- A bag the game cannot show in the hand (no clothing item of its own: carried, never worn) always keeps Loot, whatever is listed.
-- A bag that is not listed (a bag from another mod) uses the medium clip if the game can show it in the hand (it has a
-- primary-hand replacement model), otherwise Loot.

require "DSTB_Config"

local DSTB = DontSpillTheBeans

DSTB.BagClips = DSTB.BagClips or {}
local Clips = DSTB.BagClips

Clips.default = "medium"
Clips.byType = {}

local function set(clip, ids)
    for _, id in ipairs(ids) do Clips.byType[id] = clip end
end

