-- A bag with no clothing item of its own (a handbag, purse, toolbox, tote: carried, never worn) has no visual, and the game
-- builds its hand model only while it is the item in the primary hand, so the animation cannot show it: Loot.
local function carriedOnly(bag)
    return bag.getVisual and bag:getVisual() == nil
end

-- The clip for a bag item: "small", "medium", "large", "pack", "hand" or "handl", or nil for the Loot animation.
function Clips.clipFor(bag)
    if carriedOnly(bag) then return nil end
    local clip = Clips.byType[bag:getFullType()]
    if clip == nil then
        if bag.getItemReplacementPrimaryHand and bag:getItemReplacementPrimaryHand() ~= nil then return Clips.default end
        return nil
    end
    if clip == "none" then return nil end
    return clip
end

-- Why that clip, for the debug menu.
function Clips.explain(bag)
    local listed = Clips.byType[bag:getFullType()]
    local clip = Clips.clipFor(bag)
    if carriedOnly(bag) then return "Loot (carried only: no clothing item, so no hand model to show)" end
    if listed ~= nil then return (clip or "Loot") .. " (listed)" end
    return (clip or "Loot") .. (clip and " (not listed: it has a hand model, so the default)" or " (not listed: no hand model)")
end
